Lemma lsl_inv : forall pw s j J, 0 <= s -> toZ pw = 2 ^ s mod 2 ^ 63 -> toZ j = J -> 0 <= J ->
  toZ (PrimInt63.lsl pw j) = 2 ^ (s + J) mod 2 ^ 63.
Proof.
