Lemma xinside_numB_mono : forall bc b k n cb co m k' n',
  0 <= n' -> n < two64 -> 0 <= n -> k <= k' -> k' + n' <= k + n -> n' < two64 ->
  xinside_numB bc b k (ELit n) cb co m = true -> xinside_numB bc b k' (ELit n') cb co m = true.
Proof.
