Lemma img_nov_eq : forall lo hi k w, img_nov lo hi k w = true ->
  (if Z.ltb lo (Z.min k hi) then [KImg lo (Z.min k hi)] else []) ++
  (if Z.ltb (Z.max lo (k + Z.of_nat w)) hi then [KImg (Z.max lo (k + Z.of_nat w)) hi] else []) = [KImg lo hi].
Proof.
